const input = $('Execute Workflow Trigger').first().json;
const andrewContactId = 'vKJiakihiqLs3DXR6kfe';

const firstName = input.firstName || '';
const lastName = input.lastName || '';
const phone = input.phone || 'N/A';
const address = input.address || 'N/A';
const source = input.source || 'Unknown';
const roofType = input.selected_roof_type || 'N/A';
const roofSize = (input.roofSize !== undefined && input.roofSize !== null && input.roofSize !== '')
  ? `${input.roofSize} squares`
  : 'N/A';
const reason = input.project_reason || 'N/A';
const timeline = input.homeowner_timeline || 'N/A';
const insurance = input.insurance_claim_status || 'N/A';

// Estimate line (computed server-side in /api/lead-intake): priced -> range,
// none (copper) -> custom quote, anything else/missing -> line omitted.
const usd = (n) => '$' + Math.round(n).toLocaleString('en-US');
let estimateLine = '';
if (input.estimateStatus === 'priced' && Number.isFinite(Number(input.estimateLow)) && Number.isFinite(Number(input.estimateHigh)) && Number(input.estimateLow) > 0) {
  estimateLine = `\nEstimate: ${usd(Number(input.estimateLow))} \u2013 ${usd(Number(input.estimateHigh))}`;
} else if (input.estimateStatus === 'none') {
  estimateLine = '\nEstimate: none (custom quote)';
}

const message = `New ${source} lead: ${firstName} ${lastName}
Phone: ${phone}
Address: ${address}
Roof: ${roofType}
Size: ${roofSize}${estimateLine}
Reason: ${reason}
Timeline: ${timeline}
Insurance: ${insurance}`;

return [{ json: { andrewContactId, message } }];
